#include <climits>

bool checked_add(int a, int b, int& out) {
  if ((b > 0 && a > INT_MAX - b) ||
      (b < 0 && a < INT_MIN - b))
    return false;
  out = a + b;
  return true;
}

// CERT INT32-C: every division below is safe (divisor non-zero,
// and never INT_MIN / -1).
bool checked_mul(int a, int b, int& out) {
  if (a > 0) {
    if (b > 0) { if (a > INT_MAX / b) return false; }
    else       { if (b < INT_MIN / a) return false; }
  } else {
    if (b > 0) { if (a < INT_MIN / b) return false; }
    else       { if (a != 0 && b < INT_MAX / a) return false; }
  }
  out = a * b;
  return true;
}

// In practice: __builtin_add_overflow(a, b, &out) / __builtin_mul_overflow
// (GCC/Clang) - compiles to add + jo.

